  set kind(ZmidiCiEventKind value) => kindAsInt = value.value;

  /// The MUID of the peer (the new MUID for MuidChanged), 0 when the event has none.
  @ffi.Uint32()
  external int muid;

  /// Property Exchange: Request ID.
  @ffi.Uint8()
  external int request_id;

  /// Property Exchange: Number of Chunks in Message (0 when not known).
  @ffi.Uint16()
  external int chunk_total;

  /// Property Exchange: Number of This Chunk.
  @ffi.Uint16()
  external int chunk_number;

  /// PeGet, PeSet: decoded "resource", NUL-terminated.
  @ffi.Array.multi([37])
  external ffi.Array<ffi.Uint8> resource;

  /// PeGet, PeSet: decoded "resId", NUL-terminated.
  @ffi.Array.multi([37])
  external ffi.Array<ffi.Uint8> res_id;

  /// Property Exchange: Header Data.
  external ffi.Pointer<ffi.Uint8> header;

  /// Bytes of `header`.
  @ffi.UintPtr()
  external int header_len;

  /// Property Exchange: Property Data of this Chunk.
  external ffi.Pointer<ffi.Uint8> data;

  /// Bytes of `data`.
  @ffi.UintPtr()
  external int data_len;
}

/// The kind of an event: one value for each zmidi-ci Event; Property Exchange Chunks by kind.
enum ZmidiCiEventKind {
  /// No event.
  ZMIDI_CI_EVENT_KIND_NONE(0),

  /// Reply to Discovery from a new peer.
  ZMIDI_CI_EVENT_KIND_DISCOVERED(1),

  /// The Discovery window ended.
  ZMIDI_CI_EVENT_KIND_DISCOVERY_ENDED(2),

  /// This Device took a new MUID.
  ZMIDI_CI_EVENT_KIND_MUID_CHANGED(3),

  /// A peer was invalidated.
  ZMIDI_CI_EVENT_KIND_PEER_INVALIDATED(4),

  /// Reply to Endpoint Information.
  ZMIDI_CI_EVENT_KIND_ENDPOINT_INFO(5),

  /// ACK.
  ZMIDI_CI_EVENT_KIND_ACK(6),

  /// NAK.
  ZMIDI_CI_EVENT_KIND_NAK(7),

  /// Reply to Profile Inquiry: the IDs with `zmidi_ci_profile_ids`.
  ZMIDI_CI_EVENT_KIND_PROFILE_INQUIRY_REPLY(8),

  /// Profile Added, Removed, Enabled or Disabled Report.
  ZMIDI_CI_EVENT_KIND_PROFILE_REPORT(9),

  /// Set Profile On or Off to this Device: answer with `zmidi_ci_set_profile_state`.
  ZMIDI_CI_EVENT_KIND_SET_PROFILE(10),

  /// Inquiry: Profile Details to this Device: answer with `zmidi_ci_profile_details_reply`.
  ZMIDI_CI_EVENT_KIND_PROFILE_DETAILS_INQUIRY(11),

  /// Reply to Profile Details.
  ZMIDI_CI_EVENT_KIND_PROFILE_DETAILS_REPLY(12),

  /// Profile Specific Data.
  ZMIDI_CI_EVENT_KIND_PROFILE_SPECIFIC_DATA(13),

  /// Reply to Property Exchange Capabilities.
  ZMIDI_CI_EVENT_KIND_PE_CAPABILITIES(14),

  /// Inquiry: Get Property Data: answer with [`zmidi_ci_pe_reply`].
  ZMIDI_CI_EVENT_KIND_PE_GET(15),

  /// Inquiry: Set Property Data: answer with [`zmidi_ci_pe_reply`].
  ZMIDI_CI_EVENT_KIND_PE_SET(16),

  /// Subscription: the one-chunk Responder answers it with 405 in [`zmidi_ci_pe_reply`].
  ZMIDI_CI_EVENT_KIND_PE_SUBSCRIPTION(17),

  /// Reply to Get Property Data.
  ZMIDI_CI_EVENT_KIND_PE_GET_REPLY(18),

  /// Reply to Set Property Data.
  ZMIDI_CI_EVENT_KIND_PE_SET_REPLY(19),

  /// Reply to Subscription.
  ZMIDI_CI_EVENT_KIND_PE_SUBSCRIPTION_REPLY(20),

  /// Notify.
  ZMIDI_CI_EVENT_KIND_PE_NOTIFY(21),

  /// Reply to Process Inquiry Capabilities.
  ZMIDI_CI_EVENT_KIND_PI_CAPABILITIES(22),

  /// Inquiry: MIDI Message Report to this Device: answer with
  /// `zmidi_ci_message_report_reply`.
  ZMIDI_CI_EVENT_KIND_MESSAGE_REPORT(23),

  /// Reply to MIDI Message Report.
  ZMIDI_CI_EVENT_KIND_MESSAGE_REPORT_REPLY(24),

  /// End of MIDI Message Report.
  ZMIDI_CI_EVENT_KIND_MESSAGE_REPORT_END(25),

  /// A message that zmidi-ci rejected.
  ZMIDI_CI_EVENT_KIND_REJECTED(26);

  final int value;
  const ZmidiCiEventKind(this.value);

  static ZmidiCiEventKind fromValue(int value) => switch (value) {
    0 => ZMIDI_CI_EVENT_KIND_NONE,
    1 => ZMIDI_CI_EVENT_KIND_DISCOVERED,
    2 => ZMIDI_CI_EVENT_KIND_DISCOVERY_ENDED,
    3 => ZMIDI_CI_EVENT_KIND_MUID_CHANGED,
    4 => ZMIDI_CI_EVENT_KIND_PEER_INVALIDATED,
    5 => ZMIDI_CI_EVENT_KIND_ENDPOINT_INFO,
    6 => ZMIDI_CI_EVENT_KIND_ACK,
    7 => ZMIDI_CI_EVENT_KIND_NAK,
    8 => ZMIDI_CI_EVENT_KIND_PROFILE_INQUIRY_REPLY,
    9 => ZMIDI_CI_EVENT_KIND_PROFILE_REPORT,
    10 => ZMIDI_CI_EVENT_KIND_SET_PROFILE,
    11 => ZMIDI_CI_EVENT_KIND_PROFILE_DETAILS_INQUIRY,
    12 => ZMIDI_CI_EVENT_KIND_PROFILE_DETAILS_REPLY,
    13 => ZMIDI_CI_EVENT_KIND_PROFILE_SPECIFIC_DATA,
    14 => ZMIDI_CI_EVENT_KIND_PE_CAPABILITIES,
    15 => ZMIDI_CI_EVENT_KIND_PE_GET,
    16 => ZMIDI_CI_EVENT_KIND_PE_SET,
    17 => ZMIDI_CI_EVENT_KIND_PE_SUBSCRIPTION,
    18 => ZMIDI_CI_EVENT_KIND_PE_GET_REPLY,
    19 => ZMIDI_CI_EVENT_KIND_PE_SET_REPLY,
    20 => ZMIDI_CI_EVENT_KIND_PE_SUBSCRIPTION_REPLY,
    21 => ZMIDI_CI_EVENT_KIND_PE_NOTIFY,
    22 => ZMIDI_CI_EVENT_KIND_PI_CAPABILITIES,
    23 => ZMIDI_CI_EVENT_KIND_MESSAGE_REPORT,
    24 => ZMIDI_CI_EVENT_KIND_MESSAGE_REPORT_REPLY,
    25 => ZMIDI_CI_EVENT_KIND_MESSAGE_REPORT_END,
    26 => ZMIDI_CI_EVENT_KIND_REJECTED,
    _ => throw ArgumentError('Unknown value for ZmidiCiEventKind: $value'),
  };
}

