/// The kind of an event.
enum ZmidiNetEventKind {
  /// No event.
  ZMIDI_NET_EVENT_KIND_NONE(0),

  /// Host: a new Client asks for a session.
  ZMIDI_NET_EVENT_KIND_INVITATION_RECEIVED(1),

  /// Client: the Host answered Pending.
  ZMIDI_NET_EVENT_KIND_PENDING(2),

  /// Client: the Host asks for authentication; `code` is the method
  /// ([`ZMIDI_NET_AUTH_SHARED_SECRET`] or [`ZMIDI_NET_AUTH_USER`]), `value` the Authentication
  /// State (0x00 first request, 0x01 digest not correct, 0x02 Username not found).
  ZMIDI_NET_EVENT_KIND_AUTH_REQUESTED(3),

  /// Host: a failed authentication; `code` is the method, with
  /// [`ZMIDI_NET_AUTH_USERNAME_NOT_FOUND`] when the Username was not found; `value` is the
  /// count of failures of the session.
  ZMIDI_NET_EVENT_KIND_AUTH_FAILED(4),

  /// A problem with the credentials of the program; `code`: 0 no random bytes (Host), 1 no
  /// shared secret (Host), 2 empty shared secret, 3 empty password, 4 Username not valid
  /// (Client), 5 Username too long (Client).
  ZMIDI_NET_EVENT_KIND_CREDENTIALS_ERROR(5),

  /// The session is established; `code` is the authentication method, 0 for none.
  ZMIDI_NET_EVENT_KIND_ESTABLISHED(6),

  /// This side ends the session with a Bye; `code` is the Bye Reason.
  ZMIDI_NET_EVENT_KIND_ENDING(7),

  /// The session went to Idle; `code`: 0 Bye received (`value`: its Bye Reason), 1 Bye Reply,
  /// 2 Bye timeout, 3 expired, 4 ended by this side (`value`: the Bye Reason).
  ZMIDI_NET_EVENT_KIND_CLOSED(8),

  /// The session was reset.
  ZMIDI_NET_EVENT_KIND_RESET(9),

  /// This side started a Session Reset.
  ZMIDI_NET_EVENT_KIND_RESET_STARTED(10),

  /// A NAK was received; `code` is the NAK Reason.
  ZMIDI_NET_EVENT_KIND_NAK(11),

  /// A Ping Reply; `code` is the Ping Id, `value` the round-trip time in ms.
  ZMIDI_NET_EVENT_KIND_PING_REPLY(12),

  /// A Ping Reply with no open Ping; `code` is the Ping Id.
  ZMIDI_NET_EVENT_KIND_UNEXPECTED_PING_REPLY(13),

  /// The session timed out.
  ZMIDI_NET_EVENT_KIND_TIMEOUT(14),

  /// An event of the UMP Data stream (data loss, Retransmit Error).
  ZMIDI_NET_EVENT_KIND_STREAM(15),

  /// UMP Data: `word_offset` and `word_count` in the word array.
  ZMIDI_NET_EVENT_KIND_DATA(16),

  /// A diagnostic; `code`: 0 bad signature, 1 invalid peer address, 2 table full, 3 NAK sent
  /// (`value`: its NAK Reason).
  ZMIDI_NET_EVENT_KIND_DIAGNOSTIC(17);

  final int value;
  const ZmidiNetEventKind(this.value);

  static ZmidiNetEventKind fromValue(int value) => switch (value) {
    0 => ZMIDI_NET_EVENT_KIND_NONE,
    1 => ZMIDI_NET_EVENT_KIND_INVITATION_RECEIVED,
    2 => ZMIDI_NET_EVENT_KIND_PENDING,
    3 => ZMIDI_NET_EVENT_KIND_AUTH_REQUESTED,
    4 => ZMIDI_NET_EVENT_KIND_AUTH_FAILED,
    5 => ZMIDI_NET_EVENT_KIND_CREDENTIALS_ERROR,
    6 => ZMIDI_NET_EVENT_KIND_ESTABLISHED,
    7 => ZMIDI_NET_EVENT_KIND_ENDING,
    8 => ZMIDI_NET_EVENT_KIND_CLOSED,
    9 => ZMIDI_NET_EVENT_KIND_RESET,
    10 => ZMIDI_NET_EVENT_KIND_RESET_STARTED,
    11 => ZMIDI_NET_EVENT_KIND_NAK,
    12 => ZMIDI_NET_EVENT_KIND_PING_REPLY,
    13 => ZMIDI_NET_EVENT_KIND_UNEXPECTED_PING_REPLY,
    14 => ZMIDI_NET_EVENT_KIND_TIMEOUT,
    15 => ZMIDI_NET_EVENT_KIND_STREAM,
    16 => ZMIDI_NET_EVENT_KIND_DATA,
    17 => ZMIDI_NET_EVENT_KIND_DIAGNOSTIC,
    _ => throw ArgumentError('Unknown value for ZmidiNetEventKind: $value'),
  };
}

