    required ffi.Pointer<ffi.Uint8> schema,
    required int schema_len,
  }) => $allocator<ZmidiPeResource>()
    ..ref.resource = resource
    ..ref.can_get = can_get
    ..ref.can_set = can_set
    ..ref.can_subscribe = can_subscribe
    ..ref.require_res_id = require_res_id
    ..ref.fc_on_get = fc_on_get
    ..ref.fc_on_set = fc_on_set
    ..ref.can_paginate = can_paginate
    ..ref.write_defaults = write_defaults
    ..ref.encodings = encodings
    ..ref.media_type = media_type
    ..ref.schema = schema
