  /// A command or Property Data that the role does not permit.
  ZMIDI_PE_SUBSCRIPTION_ERROR_NOT_PERMITTED(4),

  /// A header value is longer than the entry buffers, or a Property is missing.
  ZMIDI_PE_SUBSCRIPTION_ERROR_INVALID(5);

  final int value;
  const ZmidiPeSubscriptionError(this.value);

  static ZmidiPeSubscriptionError fromValue(int value) => switch (value) {
    0 => ZMIDI_PE_SUBSCRIPTION_ERROR_NONE,
    1 => ZMIDI_PE_SUBSCRIPTION_ERROR_FULL,
    2 => ZMIDI_PE_SUBSCRIPTION_ERROR_NO_SUBSCRIBE_ID,
    3 => ZMIDI_PE_SUBSCRIPTION_ERROR_NOT_SUCCESS,
    4 => ZMIDI_PE_SUBSCRIPTION_ERROR_NOT_PERMITTED,
    5 => ZMIDI_PE_SUBSCRIPTION_ERROR_INVALID,
    _ => throw ArgumentError(
      'Unknown value for ZmidiPeSubscriptionError: $value',
    ),
  };
}

