/// The result of a function of the C ABI. New values go at the end only; a value never changes.
enum ZmidiStatus {
  /// The function did its work.
  ZMIDI_STATUS_OK(0),

  /// A pointer is null, or a value is out of its range. No state changed.
  ZMIDI_STATUS_INVALID_ARGUMENT(1),

  /// The output buffer of the program is too small. No state changed.
  ZMIDI_STATUS_BUFFER_TOO_SMALL(2),

  /// A reply call has no pending event to answer, or an event call has no event of its kind.
  ZMIDI_STATUS_NO_PENDING(3),

  /// The library refused the request (for example a request to an unknown peer).
  ZMIDI_STATUS_REJECTED(4),

  /// This build has no support for the request.
  ZMIDI_STATUS_NOT_SUPPORTED(5);

  final int value;
  const ZmidiStatus(this.value);

  static ZmidiStatus fromValue(int value) => switch (value) {
    0 => ZMIDI_STATUS_OK,
    1 => ZMIDI_STATUS_INVALID_ARGUMENT,
    2 => ZMIDI_STATUS_BUFFER_TOO_SMALL,
    3 => ZMIDI_STATUS_NO_PENDING,
    4 => ZMIDI_STATUS_REJECTED,
    5 => ZMIDI_STATUS_NOT_SUPPORTED,
    _ => throw ArgumentError('Unknown value for ZmidiStatus: $value'),
  };
}

