/// The interfaces, the bus speed and Alternate Setting 0 (USB-MIDI 1.0, cable-count form) of a
/// function.
final class ZmidiUsbFunctionConfig extends ffi.Struct {
  /// bInterfaceNumber of the AudioControl interface, from the USB stack.
  @ffi.Uint8()
  external int ac_interface;

  /// bInterfaceNumber of the MIDI Streaming interface, from the USB stack.
  @ffi.Uint8()
  external int ms_interface;

  /// True for high speed (480 Mb/s), false for full speed (12 Mb/s).
  @ffi.Bool()
  external bool high_speed;

  /// iInterface of the AudioControl interface; 0 is no string.
  @ffi.Uint8()
  external int ac_string;

  /// iInterface of Alternate Setting 0; 0 is no string.
  @ffi.Uint8()
  external int alt0_string;

  /// The cable count of the MIDI OUT endpoint (host to device) of Alternate Setting 0, 0 to 16.
  @ffi.Uint8()
  external int n_out;

  /// The cable count of the MIDI IN endpoint (device to host) of Alternate Setting 0, 0 to 16.
  @ffi.Uint8()
  external int n_in;

  /// The endpoint number of the MIDI OUT endpoint of Alternate Setting 0, 1 to 15.
  @ffi.Uint8()
  external int out_endpoint;

  /// The endpoint number of the MIDI IN endpoint of Alternate Setting 0, 1 to 15.
  @ffi.Uint8()
  external int in_endpoint;

  /// wMaxPacketSize of both bulk endpoints of Alternate Setting 0; 0 is the default of the bus
  /// speed (64 at full speed, 512 at high speed).
  @ffi.Uint16()
  external int max_packet;

  static ffi.Pointer<ZmidiUsbFunctionConfig> $allocate(
    ffi.Allocator $allocator, {
    required int ac_interface,
    required int ms_interface,
    required bool high_speed,
    required int ac_string,
    required int alt0_string,
    required int n_out,
    required int n_in,
    required int out_endpoint,
    required int in_endpoint,
    required int max_packet,
  }) => $allocator<ZmidiUsbFunctionConfig>()
    ..ref.ac_interface = ac_interface
    ..ref.ms_interface = ms_interface
    ..ref.high_speed = high_speed
    ..ref.ac_string = ac_string
    ..ref.alt0_string = alt0_string
    ..ref.n_out = n_out
    ..ref.n_in = n_in
    ..ref.out_endpoint = out_endpoint
    ..ref.in_endpoint = in_endpoint
    ..ref.max_packet = max_packet;
}

/// The result of [`zmidi_usb_gtb_setup`] (REQ-USB-GTB-017 to REQ-USB-GTB-019).
enum ZmidiUsbGtbResponse {
  /// The handler wrote the data stage of the answer; send it.
  ZMIDI_USB_GTB_RESPONSE_ANSWERED(0),

  /// Stall the request (USB 2.0 9.2.7). Nothing is written.
  ZMIDI_USB_GTB_RESPONSE_STALL(1),

  /// Not the Group Terminal Block descriptors request; handle it in another way.
  ZMIDI_USB_GTB_RESPONSE_NOT_HANDLED(2);

  final int value;
  const ZmidiUsbGtbResponse(this.value);

  static ZmidiUsbGtbResponse fromValue(int value) => switch (value) {
    0 => ZMIDI_USB_GTB_RESPONSE_ANSWERED,
    1 => ZMIDI_USB_GTB_RESPONSE_STALL,
    2 => ZMIDI_USB_GTB_RESPONSE_NOT_HANDLED,
    _ => throw ArgumentError('Unknown value for ZmidiUsbGtbResponse: $value'),
  };
}

/// Storage of one link. The program gives it; [`zmidi_usb_link_init`] sets it up.
final class ZmidiUsbLink extends ffi.Struct {
  /// Opaque content.
  @ffi.Array.multi([45])
  external ffi.Array<ffi.Uint64> _opaque;
}

/// The configuration of a link.
final class ZmidiUsbLinkConfig extends ffi.Struct {
  /// True on a host (the received endpoint is a MIDI IN endpoint); false on a device (MIDI OUT).
  @ffi.Bool()
  external bool host_side;

  /// The Group Terminals of the received endpoint: bit n is Group n.
  @ffi.Uint16()
  external int group_mask;

  /// wMaxPacketSize of the sent endpoint, 4 or more.
  @ffi.Uint16()
  external int max_packet;

  /// The protocol of the UMPs of the Event Packet reader: 1 MIDI 1.0 Protocol, 2 MIDI 2.0
  /// Protocol.
  @ffi.Uint32()
  external int protocol;

  static ffi.Pointer<ZmidiUsbLinkConfig> $allocate(
    ffi.Allocator $allocator, {
    required bool host_side,
    required int group_mask,
    required int max_packet,
    required int protocol,
  }) => $allocator<ZmidiUsbLinkConfig>()
    ..ref.host_side = host_side
    ..ref.group_mask = group_mask
    ..ref.max_packet = max_packet
    ..ref.protocol = protocol;
}

/// One endpoint as the writer writes it, for the endpoint allocation of the USB stack.
final class ZmidiUsbSettingEndpoint extends ffi.Struct {
  /// bAlternateSetting: 0 for USB-MIDI 1.0, 1 or more for USB MIDI 2.0.
  @ffi.Uint8()
  external int alternate_setting;

  /// bEndpointAddress: D7 direction (1 IN), D3..0 number.
  @ffi.Uint8()
  external int address;

  /// The transfer type (bmAttributes D1..0): 2 bulk, 3 interrupt.
  @ffi.Uint8()
  external int transfer;

  /// bInterval: 0 for a bulk endpoint.
  @ffi.Uint8()
  external int interval;

  /// wMaxPacketSize.
  @ffi.Uint16()
  external int max_packet;

  static ffi.Pointer<ZmidiUsbSettingEndpoint> $allocate(
    ffi.Allocator $allocator, {
    required int alternate_setting,
    required int address,
    required int transfer,
    required int interval,
    required int max_packet,
  }) => $allocator<ZmidiUsbSettingEndpoint>()
    ..ref.alternate_setting = alternate_setting
    ..ref.address = address
    ..ref.transfer = transfer
    ..ref.interval = interval
    ..ref.max_packet = max_packet;
}

/// One UMP of a received transfer.
final class ZmidiUsbUmp extends ffi.Struct {
  /// Words of the UMP, 1 to 4.
  @ffi.Uint8()
  external int word_count;

  /// The words; words after `word_count` are 0.
  @ffi.Array.multi([4])
  external ffi.Array<ffi.Uint32> words;
}
